package ratelimiter_test

import (
	"context"
	"fmt"
	"net/url"
	"testing"
	"time"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	"gopher-faucet/pkg/config"
	"gopher-faucet/pkg/nats"
	"gopher-faucet/pkg/ratelimiter"

	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/wait"
)

func TestRateLimiter(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "NatsRateLimiter Suite")
}

const (
	natsBucket = "faucet-test-bucket"
	natsTopic  = "faucet-test-topic"
)

var natsURL url.URL
var natsContainer testcontainers.Container
var ctx context.Context
var natsService *nats.NatsService
var ttl time.Duration = 1 * time.Hour

var _ = BeforeSuite(func() {
	ctx = context.Background()
	req := testcontainers.ContainerRequest{
		Image:        "nats:latest",
		ExposedPorts: []string{"4222/tcp"},
		Cmd:          []string{"-js"},
		WaitingFor:   wait.ForListeningPort("4222/tcp"),
	}
	var err error
	natsContainer, err = testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{
		ContainerRequest: req,
		Started:          true,
	})
	Expect(err).NotTo(HaveOccurred())

	endpoint, err := natsContainer.Endpoint(ctx, "")
	Expect(err).NotTo(HaveOccurred())

	u, err := url.Parse("nats://" + endpoint)
	Expect(err).NotTo(HaveOccurred())
	natsURL = *u

	natsService, err = nats.New(ctx, &config.Config{
		NatsURL:           natsURL,
		NatsTopic:         natsTopic,
		NatsBucket:        natsBucket,
		RateLimitInterval: ttl,
	})
	Expect(err).NotTo(HaveOccurred())
})

var _ = AfterSuite(func() {
	err := natsContainer.Terminate(context.Background())
	Expect(err).NotTo(HaveOccurred())
})

var _ = Describe("NatsRateLimiter", func() {
	var rl *ratelimiter.NatsRateLimiter
	BeforeEach(func() {
		var err error
		// Ensure bucket exists for cleanup, then purge it.
		kv := natsService.KV()

		keys, err := kv.Keys()
		// This should be !errors.Is(nats.ErrNoKeysFound) but it's not working
		if err != nil && err.Error() != "nats: no keys found" {
			Fail(err.Error())
		}
		for _, key := range keys {
			err := kv.Delete(key)
			Expect(err).NotTo(HaveOccurred())
		}

		rl = ratelimiter.NewNatsRateLimiter(ctx, natsBucket, kv)
	})

	Context("when checking a new IP and wallet", func() {
		It("should allow the request", func() {
			err := rl.AllowAndRecord("127.0.0.1", "wallet1", func() error {
				return nil
			})
			Expect(err).NotTo(HaveOccurred())
		})
	})

	Context("when the provided function fails", func() {
		It("should not record the request and allow a subsequent request", func() {
			err := rl.AllowAndRecord("127.0.0.1", "wallet1", func() error {
				return fmt.Errorf("operation failed")
			})
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(ContainSubstring("operation failed"))

			// The next request should be allowed because the previous one failed
			err = rl.AllowAndRecord("127.0.0.1", "wallet1", func() error {
				return nil
			})
			Expect(err).NotTo(HaveOccurred())
		})
	})

	Context("after a request has been recorded", func() {
		BeforeEach(func() {
			err := rl.AllowAndRecord("127.0.0.1", "wallet1", func() error {
				return nil
			})
			Expect(err).NotTo(HaveOccurred())
		})

		It("should not allow another request from the same IP", func() {
			err := rl.AllowAndRecord("127.0.0.1", "wallet2", func() error {
				return nil
			})
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(Equal("rate limited"))
		})

		It("should not allow another request for the same wallet", func() {
			err := rl.AllowAndRecord("127.0.0.2", "wallet1", func() error {
				return nil
			})
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(Equal("rate limited"))
		})

		It("should allow a request from a different IP and wallet", func() {
			err := rl.AllowAndRecord("127.0.0.2", "wallet2", func() error {
				return nil
			})
			Expect(err).NotTo(HaveOccurred())
		})
	})

	Context("when the rate limit interval has passed", func() {
		It("should allow another request", func() {
			shortTTL := 1 * time.Second
			topic := natsTopic + "-limit-1"
			bucket := natsBucket + "-limit-1"
			// Use a different topic and bucket so we don't mess up the other tests
			svc, err := nats.New(ctx, &config.Config{
				NatsURL:           natsURL,
				NatsTopic:         topic,
				NatsBucket:        bucket,
				RateLimitInterval: shortTTL,
			})
			Expect(err).NotTo(HaveOccurred())
			rl := ratelimiter.NewNatsRateLimiter(ctx, natsBucket, svc.KV())

			ip := fmt.Sprintf("127.0.0.1-%d", GinkgoRandomSeed())
			wallet := fmt.Sprintf("wallet-%d", GinkgoRandomSeed())

			err = rl.AllowAndRecord(ip, wallet, func() error { return nil })
			Expect(err).NotTo(HaveOccurred())

			err = rl.AllowAndRecord(ip, wallet, func() error { return nil })
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(Equal("rate limited"))

			time.Sleep(shortTTL * 2)

			err = rl.AllowAndRecord(ip, wallet, func() error { return nil })
			Expect(err).NotTo(HaveOccurred())
		})
	})

	Context("when the TTL is changed", func() {
		It("should update the bucket's TTL", func() {
			topic := natsTopic + "-limit-2"
			bucket := natsBucket + "-limit-2"
			initialTTL := 2 * time.Hour
			// Use a different topic and bucket so we don't mess up the other tests
			svc, err := nats.New(ctx, &config.Config{
				NatsURL:           natsURL,
				NatsTopic:         topic,
				NatsBucket:        bucket,
				RateLimitInterval: initialTTL,
			})
			// Initial TTL
			Expect(err).NotTo(HaveOccurred())

			status, err := svc.KV().Status()
			Expect(err).NotTo(HaveOccurred())
			Expect(status.TTL()).To(Equal(initialTTL))

			// New TTL
			newTTL := 3 * time.Hour
			svc, err = nats.New(ctx, &config.Config{
				NatsURL:           natsURL,
				NatsTopic:         topic,
				NatsBucket:        bucket,
				RateLimitInterval: newTTL,
			})
			Expect(err).NotTo(HaveOccurred())

			status, err = svc.KV().Status()
			Expect(err).NotTo(HaveOccurred())
			Expect(status.TTL()).To(Equal(newTTL))
		})
	})
})

package cosmos

import (
	"context"
	"encoding/json"
	"gopher-faucet/pkg/config"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

func TestRestClient_WaitForTxConfirmation(t *testing.T) {
	t.Run("success", func(t *testing.T) {
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			resp := map[string]interface{}{
				"tx_response": map[string]interface{}{
					"code":   0,
					"height": "12345",
				},
			}
			_ = json.NewEncoder(w).Encode(resp)
		}))
		defer server.Close()

		cfg := &config.Config{
			TxnPollTimeout:   5 * time.Second,
			TxnPollFrequency: 10 * time.Millisecond,
			CosmosRestUrl:    server.URL,
		}
		client := NewRestClient(cfg, server.Client())

		height, err := client.WaitForTxConfirmation(context.Background(), "TEST_HASH")
		require.NoError(t, err)
		require.Equal(t, int64(12345), height)
	})

	t.Run("timeout", func(t *testing.T) {
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			http.NotFound(w, r)
		}))
		defer server.Close()

		cfg := &config.Config{
			TxnPollTimeout:   50 * time.Millisecond,
			TxnPollFrequency: 10 * time.Millisecond,
			CosmosRestUrl:    server.URL,
		}
		client := NewRestClient(cfg, server.Client())

		_, err := client.WaitForTxConfirmation(context.Background(), "TEST_HASH")
		require.Error(t, err)
		require.Contains(t, err.Error(), "timed out")
	})

	t.Run("failed tx", func(t *testing.T) {
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			resp := map[string]interface{}{
				"tx_response": map[string]interface{}{
					"code":    5,
					"raw_log": "insufficient funds",
				},
			}
			_ = json.NewEncoder(w).Encode(resp)
		}))
		defer server.Close()

		cfg := &config.Config{
			TxnPollTimeout:   5 * time.Second,
			TxnPollFrequency: 10 * time.Millisecond,
			CosmosRestUrl:    server.URL,
		}
		client := NewRestClient(cfg, server.Client())

		_, err := client.WaitForTxConfirmation(context.Background(), "TEST_HASH")
		require.Error(t, err)
		require.Contains(t, err.Error(), "transaction TEST_HASH failed with code 5")
	})

	t.Run("transient error", func(t *testing.T) {
		requestCount := 0
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if requestCount < 2 {
				w.WriteHeader(http.StatusInternalServerError)
				requestCount++
				return
			}
			resp := map[string]interface{}{
				"tx_response": map[string]interface{}{
					"code":   0,
					"height": "12345",
				},
			}
			_ = json.NewEncoder(w).Encode(resp)
		}))
		defer server.Close()

		cfg := &config.Config{
			TxnPollTimeout:   5 * time.Second,
			TxnPollFrequency: 10 * time.Millisecond,
			CosmosRestUrl:    server.URL,
		}
		client := NewRestClient(cfg, server.Client())

		height, err := client.WaitForTxConfirmation(context.Background(), "TEST_HASH")
		require.NoError(t, err)
		require.Equal(t, int64(12345), height)
	})
}

