package ratelimiter

import (
	"context"
	"fmt"
	"strings"
	"sync"

	"github.com/nats-io/nats.go"
	"gopher-faucet/pkg/util"
)

// NatsRateLimiter provides a thread-safe, in-memory rate limiter.
type NatsRateLimiter struct {
	kv       nats.KeyValue
	inFlight *util.Set[string]
	mu       sync.Mutex
}

// NewNatsRateLimiter creates a new rate limiter with NATS KV persistence.
func NewNatsRateLimiter(ctx context.Context, bucket string, kv nats.KeyValue) *NatsRateLimiter {
	return &NatsRateLimiter{
		kv:       kv,
		inFlight: util.NewSet[string](),
	}
}

// AllowAndRecord checks if a request is allowed, executes the provided function,
// and records the request if the function succeeds.
func (r *NatsRateLimiter) AllowAndRecord(ip, wallet string, fn func() error) error {
	safeIP := strings.ReplaceAll(ip, ":", "-")
	ipKey := "ip-" + safeIP
	walletKey := "wallet-" + wallet

	if !r.allow(ipKey, walletKey) {
		return fmt.Errorf("rate limited")
	}

	if err := fn(); err != nil {
		r.mu.Lock()
		defer r.mu.Unlock()
		r.inFlight.Delete(ipKey)
		r.inFlight.Delete(walletKey)
		return fmt.Errorf("failed to execute function: %w", err)
	}

	if err := r.record(ipKey, walletKey); err != nil {
		return fmt.Errorf("failed to record: %w", err)
	}

	return nil
}

// allow checks if a request is allowed for a given IP and wallet.
func (r *NatsRateLimiter) allow(ipKey, walletKey string) bool {
	r.mu.Lock()
	defer r.mu.Unlock()

	if r.inFlight.Contains(ipKey) {
		return false
	}
	if r.inFlight.Contains(walletKey) {
		return false
	}

	if _, err := r.kv.Get(ipKey); err == nil {
		return false
	}

	if _, err := r.kv.Get(walletKey); err == nil {
		return false
	}

	// We record these in inFlight here to include them in the critical section
	r.inFlight.Add(ipKey)
	r.inFlight.Add(walletKey)

	return true
}

// record records a request for a given IP and wallet, setting the expiry time.
func (r *NatsRateLimiter) record(ipKey, walletKey string) error {
	if _, err := r.kv.Put(ipKey, []byte{}); err != nil {
		return fmt.Errorf("failed to record ip %s: %w", ipKey, err)
	}

	if _, err := r.kv.Put(walletKey, []byte{}); err != nil {
		return fmt.Errorf("failed to record wallet %s: %w", walletKey, err)
	}

	r.mu.Lock()
	defer r.mu.Unlock()
	r.inFlight.Delete(ipKey)
	r.inFlight.Delete(walletKey)

	return nil
}

package slack

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
)

// SendMessage sends a message to the configured Slack webhook URL.
func SendMessage(webhookURL, message string) error {
	if webhookURL == "" {
		return nil // Do nothing if webhook URL is not set
	}

	payload, err := json.Marshal(map[string]string{"text": message})
	if err != nil {
		return err
	}

	resp, err := http.Post(webhookURL, "application/json", bytes.NewBuffer(payload))
	if err != nil {
		return err
	}
	defer resp.Body.Close() //nolint:errcheck

	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("failed to send slack message, status code: %d", resp.StatusCode)
	}

	return nil
}

package xlog

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"runtime"
	"strconv"
	"strings"
)

var (
	logger  *slog.Logger
	leveler *slog.LevelVar
)

func init() {
	leveler = new(slog.LevelVar)
	level, err := ParseLevel(os.Getenv("LOG_LEVEL"))
	if err != nil {
		level = slog.LevelDebug
	}
	leveler.Set(level)

	var opts = &slog.HandlerOptions{
		Level: leveler,
	}
	handler := slog.NewJSONHandler(os.Stdout, opts)
	logger = slog.New(handler)
}

func SetLevel(levelStr string) error {
	level, err := ParseLevel(levelStr)
	if err != nil {
		return err
	}
	leveler.Set(level)
	Warn("Log level set", "level", leveler.Level().String())
	return nil
}

func GetLevel() slog.Level {
	return leveler.Level()
}

func ParseLevel(lvl string) (slog.Level, error) {
	l, err := strconv.Atoi(lvl)
	if err == nil {
		return slog.Level(l), nil
	}
	switch strings.ToLower(lvl) {
	case "error":
		return slog.LevelError, nil
	case "warning", "warn":
		return slog.LevelWarn, nil
	case "info":
		return slog.LevelInfo, nil
	case "debug":
		return slog.LevelDebug, nil
	}
	return slog.Level(0), fmt.Errorf("unknown log level: %s", lvl)
}

func _log(level slog.Level, msg string, args ...any) {
	_, f, l, _ := runtime.Caller(2)
	group := slog.Group(
		"source",
		slog.Attr{
			Key:   "filename",
			Value: slog.AnyValue(f),
		},
		slog.Attr{
			Key:   "lineno",
			Value: slog.AnyValue(l),
		},
	)
	args = append(args, group)
	logger.Log(context.Background(), level, msg, args...)
}

func Info(msg string, args ...any) {
	_log(slog.LevelInfo, msg, args...)
}

func Debug(msg string, args ...any) {
	_log(slog.LevelDebug, msg, args...)
}

func Error(msg string, args ...any) {
	_log(slog.LevelError, msg, args...)
}

func Warn(msg string, args ...any) {
	_log(slog.LevelWarn, msg, args...)
}

func Fatal(msg string, args ...any) {
	_log(slog.LevelError, msg, args...)
	os.Exit(1)
}

