	"net/http"
	"sync"

	"github.com/nats-io/nats.go"
)

// Manager manages a collection of workers and provides access to their wallet information.
type Manager struct {
	workers []*Worker
	mu      sync.RWMutex
}

// NewManager creates a new worker manager.
func NewManager() *Manager {
	return &Manager{
		workers: make([]*Worker, 0),
	}
}

// AddWorker adds a worker to the manager.
func (m *Manager) AddWorker(w *Worker) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.workers = append(m.workers, w)
}

// GetWalletInfo retrieves all wallet information from managed workers.
func (m *Manager) GetWalletInfo(ctx context.Context) ([]server.WalletInfo, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	wallets := make([]server.WalletInfo, 0, len(m.workers))
	for _, w := range m.workers {
		balance, err := w.GetBalance(ctx)
		if err != nil {
			// Continue collecting other wallets even if one fails
			wallets = append(wallets,
				server.WalletInfo{
					Wallet:   w.Address(),
					Balance:  0,
					Denom:    "error",
					IsFunded: w.IsFunded(),
				})
			xlog.Error("Error while getting wallet balance", "worker", w.workerID, "wallet", w.Address(), "error", err)
			continue
		}

		wallets = append(wallets, server.WalletInfo{
			Wallet:   w.Address(),
			Balance:  balance.Amount.Int64(),
			Denom:    balance.Denom,
			IsFunded: w.IsFunded(),
		})
	}

	return wallets, nil
}

// StartWorkers creates and starts all workers.
func (m *Manager) StartWorkers(ctx context.Context, cfg *config.Config, met *metrics.Metrics, httpClient *http.Client, broadcastSemaphore chan struct{}, pullSub *nats.Subscription) error {
	for i := uint(0); i < cfg.NumWorkers; i++ {
		w, err := NewWorker(cfg, i, met, httpClient, broadcastSemaphore)
		if err != nil {
			return err
		}
		balance, err := w.GetBalance(ctx)
		if err != nil {
			xlog.Error("failed to get worker balance", "id", i, "address", w.Address(), "error", err)
		}
		xlog.Info("worker wallet", "id", i, "address", w.Address(), "balance", balance.String())
		m.AddWorker(w)
		go w.Start(ctx, pullSub)
	}
	return nil
}

