type Config struct {
	FaucetHome           string        `env:"FAUCET_HOME,required"`
	ListenAddr           string        `env:"LISTEN_ADDR,default=:8080"`
	LogLevel             string        `env:"LOG_LEVEL,default=info"`
	RawFaucetAmount      string        `env:"FAUCET_AMOUNT,required"`
	NumWorkers           uint          `env:"NUM_WORKERS,default=10"`
	BatchSize            uint          `env:"BATCH_SIZE,default=10"`
	BatchTimeout         time.Duration `env:"BATCH_TIMEOUT,default=5s"`
	MinTxnWait           time.Duration `env:"MIN_TXN_WAIT,default=5s"`
	ConcurrentBroadcasts uint          `env:"CONCURRENT_BROADCASTS,default=10"`
	MaxRetries           uint          `env:"MAX_RETRIES,default=5"`
	RetryDelay           time.Duration `env:"RETRY_DELAY,default=1s"`
	BackoffFactor        float64       `env:"BACKOFF_FACTOR,default=2.0"`
	MaxRetryDelay        time.Duration `env:"MAX_RETRY_DELAY,default=30s"`
	RateLimitInterval    time.Duration `env:"RATE_LIMIT_INTERVAL,default=24h"`
	RawLowWaterAmount    string        `env:"WALLET_LOW_WATER_AMOUNT"`
	SlackWebhookURL      url.URL       `env:"SLACK_WEBHOOK_URL"`
	NatsURL              url.URL       `env:"NATS_URL,required"`
	NatsTopic            string        `env:"NATS_TOPIC,default=gopher-faucet"`
	NatsBucket           string        `env:"NATS_BUCKET,default=gopher-faucet"`
	CosmosRpcUrl         string        `env:"COSMOS_RPC_URL,default=http://localhost:26657"`
	CosmosRestUrl        string        `env:"COSMOS_REST_URL,default=http://localhost:1317"`
	ChainID              string        `env:"CHAIN_ID,required"`
	GasLimit             uint64        `env:"GAS_LIMIT,default=200000"`
	GasAdjustment        float64       `env:"GAS_ADJUSTMENT,default=1.5"`
	RawGasPrices         string        `env:"GAS_PRICES,default=0.025"`
	Denom                string        `env:"DENOM,required"`
	Bech32Prefix         string        `env:"BECH32_PREFIX,default=gopher"`
	TxnPollFrequency     time.Duration `env:"TXN_POLL_FREQUENCY,default=1s"`
	TxnPollTimeout       time.Duration `env:"TXN_POLL_TIMEOUT,default=10m"`

	// GasPrices holds the parsed value of RawGasPrices + Denom
	GasPrices sdk.DecCoins
	// ParsedFaucetAmount holds the parsed value of FaucetAmount + Denom
	FaucetAmount sdk.Coin
	// ParsedWalletLowWaterAmount holds the parsed value of WalletLowWaterAmount + Denom
	WalletLowWaterAmount sdk.Coin
}

func Get() *Config {
	var cfg Config
	if err := envconfig.Process(context.Background(), &cfg); err != nil {
		xlog.Fatal("failed to process config", err)
	}

	if cfg.BatchTimeout.Nanoseconds() < cfg.MinTxnWait.Nanoseconds() {
		xlog.Fatal("BATCH_TIMEOUT must be greater than or equal to MIN_TXN_WAIT")
	}

	// Parse the gas prices
	gasPrices, err := sdk.ParseDecCoins(fmt.Sprintf("%s%s", cfg.RawGasPrices, cfg.Denom))
	if err != nil {
		xlog.Fatal("invalid gas prices configuration", err)
	}
	cfg.GasPrices = gasPrices

	// Parse the faucet amount once at startup
	faucetAmount, ok := math.NewIntFromString(cfg.RawFaucetAmount)
	if !ok {
		xlog.Fatal("invalid faucet amount configuration")
	}
	cfg.FaucetAmount = sdk.NewCoin(cfg.Denom, faucetAmount)

	// Parse the low water amount if it is set
	if cfg.RawLowWaterAmount != "" {
		lowWaterAmount, ok := math.NewIntFromString(cfg.RawLowWaterAmount)
		if !ok {
			xlog.Fatal("invalid low water amount configuration")
		}
		cfg.WalletLowWaterAmount = sdk.NewCoin(cfg.Denom, lowWaterAmount)
	}

	return &cfg
}

package main

import (
	"context"
	"encoding/json"
	"net/http"
	"os/signal"
	"strings"
	"syscall"
	"time"

	"cosmossdk.io/math"
	sdk "github.com/cosmos/cosmos-sdk/types"
	"github.com/prometheus/client_golang/prometheus"

	"gopher-faucet/pkg/config"
	"gopher-faucet/pkg/metrics"
	"gopher-faucet/pkg/nats"
	"gopher-faucet/pkg/server"
	"gopher-faucet/pkg/worker"
	"gopher-faucet/pkg/xlog"
)

func main() {
	cfg := config.Get()

	// Set log level
	if err := xlog.SetLevel(cfg.LogLevel); err != nil {
		xlog.Fatal("failed to set log level", "error", err)
	}

	// Set Bech32 prefix
	xlog.Debug("Setting Bech32 prefix", "prefix", cfg.Bech32Prefix)
	sdkCfg := sdk.GetConfig()
	sdkCfg.SetBech32PrefixForAccount(cfg.Bech32Prefix, cfg.Bech32Prefix+"pub")
	sdkCfg.SetBech32PrefixForConsensusNode(cfg.Bech32Prefix, cfg.Bech32Prefix+"pub")
	sdkCfg.SetBech32PrefixForValidator(cfg.Bech32Prefix, cfg.Bech32Prefix+"pub")
	sdkCfg.Seal()

	// Register denominations
	microDenom := cfg.Denom
	baseDenom := strings.TrimPrefix(microDenom, "u")
	if err := sdk.RegisterDenom(microDenom, math.LegacyOneDec()); err != nil {
		xlog.Fatal("failed to create micro denomination", "denom", microDenom, "error", err)
	}
	if err := sdk.RegisterDenom(baseDenom, math.LegacyNewDec(1000000)); err != nil {
		xlog.Fatal("failed to create base denomination", "denom", baseDenom, "error", err)
	}

	// Wait for the node to be ready before starting workers
	waitForNode(cfg)

	interruptCtx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	natsService, err := nats.New(interruptCtx, cfg)
	if err != nil {
		xlog.Fatal("failed to connect to nats", "error", err)
	}
	defer natsService.Close()

	// Create pull subscription to the faucet queue
	pullSub, err := natsService.PullSubscribe()
	if err != nil {
		xlog.Fatal("failed to subscribe to nats queue", "error", err)
	}

	defer func() {
		err := pullSub.Unsubscribe()
		if err != nil {
			xlog.Error("Error while unsubscribing from nats queue", "error", err)
		}
	}()

	// Create metrics
	m := metrics.New(prometheus.DefaultRegisterer)

	// Create a semaphore to limit concurrent broadcasts
	broadcastSemaphore := make(chan struct{}, cfg.ConcurrentBroadcasts)

	// Create a shared HTTP client with connection pooling
	httpClient := &http.Client{
		Transport: &http.Transport{
			MaxIdleConns:        100,
			MaxIdleConnsPerHost: 10,
			IdleConnTimeout:     30 * time.Second,
		},
		Timeout: 30 * time.Second,
	}

	// Create worker manager and start workers
	workerManager := worker.NewManager()
	if err := workerManager.StartWorkers(interruptCtx, cfg, m, httpClient, broadcastSemaphore, pullSub); err != nil {
		xlog.Fatal("failed to start workers", "error", err)
	}

	// Create and start the server
	srv, err := server.CreateServer(interruptCtx, cfg, natsService, workerManager, m)
	if err != nil {
		xlog.Fatal("failed to create server", "error", err)
	}

	go func() {
		if err := srv.Start(cfg.ListenAddr); err != nil && err != http.ErrServerClosed {
			xlog.Fatal("shutting down the server", "error", err)
		}
	}()

	// Listen for the interrupt signal.
	<-interruptCtx.Done()
	stop()
	xlog.Info("shutting down gracefully, press Ctrl+C again to force")

	// The context is used to inform the server it has 5 seconds to finish
	// the requests it is currently handling
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		xlog.Fatal("server forced to shutdown", "error", err)
	}

	xlog.Info("server exiting")
}

// waitForNode polls the Cosmos node's REST endpoint until it is ready.
func waitForNode(cfg *config.Config) {
	xlog.Info("Waiting for Cosmos node to be ready...")

	ticker := time.NewTicker(3 * time.Second)
	defer ticker.Stop()
	statusUrl := cfg.CosmosRestUrl + "/cosmos/base/tendermint/v1beta1/syncing"

	timeoutCtx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()

	for {
		select {
		case <-timeoutCtx.Done():
			xlog.Fatal("timed out waiting for Cosmos node to be ready")
		case <-ticker.C:
			resp, err := http.Get(statusUrl)
			if err != nil {
				xlog.Warn("failed to get node status from REST API, will retry...", "error", err)
				continue
			}
			defer resp.Body.Close() // nolint:errcheck

			if resp.StatusCode != http.StatusOK {
				xlog.Warn("node status endpoint returned non-200 status, will retry...", "status", resp.Status)
				continue
			}

			var status struct {
				Syncing bool `json:"syncing"`
			}
			if err := json.NewDecoder(resp.Body).Decode(&status); err != nil {
				xlog.Warn("failed to decode node status, will retry...", "error", err)
				continue
			}

			if !status.Syncing {
				xlog.Info("Cosmos node is ready")
				return
			}
			xlog.Info("Node is not ready yet (still syncing)...")
		}
	}
}

package cosmos

import (
	"context"
	"encoding/json"
	"fmt"
	"gopher-faucet/pkg/config"
	"gopher-faucet/pkg/xlog"
	"io"
	"net/http"
	"time"

	sdk "github.com/cosmos/cosmos-sdk/types"
)

// RestClient defines a client for interacting with a Cosmos REST endpoint.
type RestClient struct {
	cfg        *config.Config
	httpClient *http.Client
	restURL    string
}

// NewRestClient creates a new Cosmos REST client.
func NewRestClient(cfg *config.Config, httpClient *http.Client) *RestClient {
	return &RestClient{
		cfg:        cfg,
		httpClient: httpClient,
		restURL:    cfg.CosmosRestUrl,
	}
}

// CheckStatus performs a status check against the Cosmos REST endpoint.
func (c *RestClient) CheckStatus(ctx context.Context) error {
	req, err := http.NewRequestWithContext(ctx, "GET", c.restURL+"/cosmos/base/tendermint/v1beta1/syncing", nil)
	if err != nil {
		return fmt.Errorf("failed to create request: %w", err)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("failed to get node status from REST API: %w", err)
	}
	defer func() {
		if err := resp.Body.Close(); err != nil {
			xlog.Warn("failed to close response body", "error", err)
		}
	}()

	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("node status endpoint returned non-200 status: %s", resp.Status)
	}

	var status struct {
		Syncing bool `json:"syncing"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&status); err != nil {
		return fmt.Errorf("failed to decode node status: %w", err)
	}

	if status.Syncing {
		return fmt.Errorf("node is still syncing")
	}

	return nil
}

func (c *RestClient) GetBalance(ctx context.Context, address, denom string) (sdk.Coin, error) {
	// Use the REST API to get the balance, bypassing client-side decoding issues.
	url := fmt.Sprintf("%s/cosmos/bank/v1beta1/balances/%s/by_denom?denom=%s", c.restURL, address, denom)
	xlog.Debug("getting balance from REST API", "url", url)

	resp, err := c.httpClient.Get(url)
	if err != nil {
		return sdk.Coin{}, fmt.Errorf("failed to get balance from REST API: %w", err)
	}
	defer func() {
		if err := resp.Body.Close(); err != nil {
			xlog.Warn("failed to close response body", "error", err)
		}
	}()

	if resp.StatusCode == http.StatusNotFound {
		// Note: The Cosmos SDK bank balance endpoint returns zero balance for non-existent
		// accounts, not 404. A 404 here likely indicates an infrastructure issue (e.g.,
		// ingress controller returning 404 during pod restart). Return an error so callers
		// can keep their cached balance instead of incorrectly assuming zero.
		return sdk.Coin{}, fmt.Errorf("received 404 from balance endpoint (likely infrastructure issue): %s", url)
	}

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return sdk.Coin{}, fmt.Errorf("failed to get balance from REST API: status code %d, body: %s", resp.StatusCode, string(body))
	}

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return sdk.Coin{}, fmt.Errorf("failed to read response body: %w", err)
	}

	var balanceResp struct {
		Balance sdk.Coin `json:"balance"`
	}
	if err := json.Unmarshal(body, &balanceResp); err != nil {
		return sdk.Coin{}, fmt.Errorf("failed to unmarshal balance response: %w, body: %s", err, string(body))
	}

	return balanceResp.Balance, nil
}

func (c *RestClient) GetAccountDetails(ctx context.Context, address string) (uint64, uint64, error) {
	url := fmt.Sprintf("%s/cosmos/auth/v1beta1/accounts/%s", c.restURL, address)
	xlog.Debug("getting account details from REST API", "url", url)

	resp, err := c.httpClient.Get(url)
	if err != nil {
		return 0, 0, fmt.Errorf("failed to get account details from REST API: %w", err)
	}
	defer func() {
		if err := resp.Body.Close(); err != nil {
			xlog.Warn("failed to close response body", "error", err)
		}
	}()

	if resp.StatusCode == http.StatusNotFound {
		xlog.Info("account not found on chain, assuming account number 0 and sequence 0", "address", address)
		return 0, 0, nil
	}

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return 0, 0, fmt.Errorf("failed to get account details from REST API: status code %d, body: %s", resp.StatusCode, string(body))
	}

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return 0, 0, fmt.Errorf("failed to read response body: %w", err)
	}

	var respJSON map[string]json.RawMessage
	if err := json.Unmarshal(body, &respJSON); err != nil {
		return 0, 0, fmt.Errorf("failed to unmarshal account response wrapper: %w, body: %s", err, string(body))
	}

	accBytes, ok := respJSON["account"]
	if !ok {
		return 0, 0, fmt.Errorf("account field not found in response: %s", string(body))
	}

	var acc struct {
		AccountNumber uint64 `json:"account_number,string"`
		Sequence      uint64 `json:"sequence,string"`
	}
	if err := json.Unmarshal(accBytes, &acc); err != nil {
		// Fallback for ethermint accounts which have a different structure
		var ethAcc struct {
			BaseAccount struct {
				AccountNumber uint64 `json:"account_number,string"`
				Sequence      uint64 `json:"sequence,string"`
			} `json:"base_account"`
		}
		if err := json.Unmarshal(accBytes, &ethAcc); err != nil {
			return 0, 0, fmt.Errorf("failed to unmarshal account JSON: %w, body: %s", err, string(accBytes))
		}
		return ethAcc.BaseAccount.AccountNumber, ethAcc.BaseAccount.Sequence, nil
	}

	return acc.AccountNumber, acc.Sequence, nil
}

func (c *RestClient) WaitForTxConfirmation(ctx context.Context, txHash string) (int64, error) {
	timeout := time.After(c.cfg.TxnPollTimeout)
	ticker := time.NewTicker(c.cfg.TxnPollFrequency)
	defer ticker.Stop()

	url := fmt.Sprintf("%s/cosmos/tx/v1beta1/txs/%s", c.restURL, txHash)

	for {
		select {
		case <-ctx.Done():
			return 0, ctx.Err()
		case <-timeout:
			return 0, fmt.Errorf("timed out waiting for transaction confirmation for tx %s", txHash)
		case <-ticker.C:
			resp, err := c.httpClient.Get(url)
			if err != nil {
				xlog.Warn("failed to get tx details, retrying...", "error", err)
				continue // Treat as transient error and retry
			}

			if resp.StatusCode == http.StatusNotFound {
				xlog.Debug("transaction not found, retrying...", "hash", txHash)
				if err := resp.Body.Close(); err != nil {
					xlog.Warn("failed to close response body", "error", err)
				}
				continue
			}

			if resp.StatusCode != http.StatusOK {
				body, _ := io.ReadAll(resp.Body)
				xlog.Warn("received non-200 status code while polling for tx, retrying...", "status", resp.Status, "body", string(body))
				if err := resp.Body.Close(); err != nil {
					xlog.Warn("failed to close response body", "error", err)
				}
				continue
			}

			body, err := io.ReadAll(resp.Body)
			if err := resp.Body.Close(); err != nil {
				xlog.Warn("failed to close response body", "error", err)
			}
			if err != nil {
				xlog.Warn("failed to read response body, retrying...", "error", err)
				continue
			}

			var minimalResp struct {
				TxResponse struct {
					Code   uint32 `json:"code"`
					Height int64  `json:"height,string"`
					RawLog string `json:"raw_log"`
				} `json:"tx_response"`
			}
			if err := json.Unmarshal(body, &minimalResp); err != nil {
				xlog.Warn("failed to unmarshal tx response, retrying...", "error", err, "body", string(body))
				continue
			}

			if minimalResp.TxResponse.Code != 0 {
				return 0, fmt.Errorf("transaction %s failed with code %d: %s", txHash, minimalResp.TxResponse.Code, minimalResp.TxResponse.RawLog)
			}

			return minimalResp.TxResponse.Height, nil
		}
	}
}

package server

import (
	"context"
	"fmt"
	"gopher-faucet/pkg/config"
	"gopher-faucet/pkg/cosmos"
	"gopher-faucet/pkg/metrics"
	"gopher-faucet/pkg/nats"
	"gopher-faucet/pkg/ratelimiter"
	"gopher-faucet/pkg/xlog"
	"net/http"
	"net/http/pprof"
	"time"

	"github.com/labstack/echo-contrib/echoprometheus"
	"github.com/labstack/echo/v4"
	"github.com/labstack/echo/v4/middleware"
	natsapi "github.com/nats-io/nats.go"
	"github.com/prometheus/client_golang/prometheus"
)

// New sets up and returns a new Server.
func New(cfg *config.Config, limiter RateLimiter, natsService NatsService, cosmosClient CosmosStatusChecker, wip WalletInfoProvider, m *metrics.Metrics, reg prometheus.Registerer, gatherer prometheus.Gatherer) *Server {
	e := echo.New()
	e.HideBanner = true
	s := &Server{
		cfg:     cfg,
		echo:    e,
		limiter: limiter,
		nats:    natsService,
		cosmos:  cosmosClient,
		metrics: m,
		wallets: wip,
	}

	// Enable metrics middleware
	if reg == nil {
		reg = prometheus.DefaultRegisterer
	}
	if gatherer == nil {
		gatherer = prometheus.DefaultGatherer
	}
	e.Use(echoprometheus.NewMiddlewareWithConfig(echoprometheus.MiddlewareConfig{
		Registerer: reg,
	}))

	e.Use(middleware.Logger())
	e.Use(middleware.Recover())

	e.GET("/api/v1/faucet", s.handleFaucetRequest)
	e.GET("/healthz", s.handleHealthz)
	e.GET("/readyz", s.handleReadyz)

	// Add debug routes
	debugGroup := e.Group("/debug")
	debugGroup.GET("/wallets", s.handleWallets)
	debugGroup.GET("/loglevel", s.handleGetLogLevel)
	debugGroup.PUT("/loglevel", s.handleSetLogLevel)
	debugGroup.GET("/metrics", echoprometheus.NewHandlerWithConfig(echoprometheus.HandlerConfig{
		Gatherer: gatherer,
	}))

	// Add pprof routes under debug group
	pprofGroup := debugGroup.Group("/pprof")
	pprofGroup.GET("/*", echo.WrapHandler(http.HandlerFunc(pprof.Index)))
	pprofGroup.GET("/cmdline", echo.WrapHandler(http.HandlerFunc(pprof.Cmdline)))
	pprofGroup.GET("/profile", echo.WrapHandler(http.HandlerFunc(pprof.Profile)))
	pprofGroup.GET("/symbol", echo.WrapHandler(http.HandlerFunc(pprof.Symbol)))
	pprofGroup.GET("/trace", echo.WrapHandler(http.HandlerFunc(pprof.Trace)))

	return s
}

// Start begins listening for requests.
func (s *Server) Start(address string) error {
	if err := s.echo.Start(address); err != nil {
		return fmt.Errorf("failed to start echo server: %w", err)
	}
	return nil
}

// Shutdown gracefully shuts down the server.
func (s *Server) Shutdown(ctx context.Context) error {
	if err := s.echo.Shutdown(ctx); err != nil {
		return fmt.Errorf("failed to shutdown echo server: %w", err)
	}
	return nil
}

func (s *Server) handleFaucetRequest(c echo.Context) error {
	wallet := c.QueryParam("wallet")
	clientIP := c.QueryParam("client_ip")

	if wallet == "" || clientIP == "" {
		return c.String(http.StatusBadRequest, "wallet and client_ip are required")
	}

	err := s.limiter.AllowAndRecord(clientIP, wallet, func() error {
		return s.nats.Publish(wallet)
	})
	if err != nil {
		if err.Error() == "rate limited" {
			return c.String(http.StatusTooManyRequests, "rate limited")
		}
		xlog.Error("failed to publish to nats", "error", err)
		return c.String(http.StatusInternalServerError, "internal server error")
	}

	return c.String(http.StatusOK, "OK")
}

func (s *Server) handleHealthz(c echo.Context) error {
	return c.String(http.StatusOK, "OK")
}

func (s *Server) handleReadyz(c echo.Context) error {
	if s.nats.Status() != natsapi.CONNECTED {
		return c.String(http.StatusServiceUnavailable, "NATS not connected")
	}

	ctx, cancel := context.WithTimeout(c.Request().Context(), 2*time.Second)
	defer cancel()
	if err := s.cosmos.CheckStatus(ctx); err != nil {
		xlog.Error("cosmos rpc readiness check failed", "error", err)
		return c.String(http.StatusServiceUnavailable, "Cosmos RPC not connected")
	}

	return c.String(http.StatusOK, "OK")
}

func (s *Server) handleWallets(c echo.Context) error {
	if s.wallets == nil {
		return c.String(http.StatusServiceUnavailable, "Wallet info provider not configured")
	}

	ctx, cancel := context.WithTimeout(c.Request().Context(), 10*time.Second)
	defer cancel()

	wallets, err := s.wallets.GetWalletInfo(ctx)
	if err != nil {
		xlog.Error("failed to get wallets", "error", err)
		return c.String(http.StatusInternalServerError, "Failed to retrieve wallet information")
	}

	return c.JSON(http.StatusOK, wallets)
}

func (s *Server) handleGetLogLevel(c echo.Context) error {
	currentLevel := xlog.GetLevel()
	return c.JSON(http.StatusOK, map[string]string{
		"level": currentLevel.String(),
	})
}

func (s *Server) handleSetLogLevel(c echo.Context) error {
	levelParam := c.QueryParam("level")

	// If no parameter is given, reset to the configured default
	if levelParam == "" {
		if err := xlog.SetLevel(s.cfg.LogLevel); err != nil {
			xlog.Error("failed to set configured log level", "error", err)
			return c.String(http.StatusInternalServerError, "Failed to set configured log level")
		}
		return c.String(http.StatusOK, fmt.Sprintf("Log level reset to configured default: %s", xlog.GetLevel().String()))
	}

	// Set the new log level
	if err := xlog.SetLevel(levelParam); err != nil {
		return c.String(http.StatusBadRequest, fmt.Sprintf("Invalid log level: %s", levelParam))
	}

	return c.String(http.StatusOK, fmt.Sprintf("Log level set to: %s", xlog.GetLevel().String()))
}

// CreateServer initializes the server and its dependencies.
func CreateServer(ctx context.Context, cfg *config.Config, natsService *nats.NatsService, wip WalletInfoProvider, m *metrics.Metrics) (*Server, error) {
	limiter := ratelimiter.NewNatsRateLimiter(ctx, cfg.NatsBucket, natsService.KV())

	cosmosClient := cosmos.NewRestClient(cfg, http.DefaultClient)

	return New(cfg, limiter, natsService, cosmosClient, wip, m, nil, nil), nil
}
